  [['tab after comma', '\"x,\\ty\"'], ['multiple commas', '\"x,  y, z\"'], ['Unicode and escaped quote combined', '\"😀,\"\"é\"\"\"'], ['embedded CRLF', '\"x,\\r\\ny\"']],
  [['tab before comma', '\"x\\t,y\"'], ['boundary numbers combined', '\"0,-1,999999999999999999999\"'], ['empty comma segments', '\",,x,\"'], ['multiline escaped quote', '\"x,\\n\"\"y\"\"\"']]
];
for (let r = 0; r < rounds.length; r++) {
  console.log('ROUND ' + (r + 1));
  for (const [name, field] of rounds[r]) {
    const input = 'id,value\\n1,' + field + '\\n';
    let output = '';
    const sandbox = {
      require: name => { if (name === 'fs') return {readFileSync: () => input}; throw Error(name); },
      process: {argv: ['node','dedupe.js','inline.csv','id'], stdout: {write: s => output += s}, exit: n => {throw Error('exit ' + n);}},
      console: {error: s => {throw Error(s);}}
    };
    try {
      vm.runInNewContext(source, sandbox, {filename: 'dedupe.js'});
      console.log(JSON.stringify({name, pass: output === input, input, output}));
    } catch (e) { console.log(JSON.stringify({name, error:e.message})); }
  }
}
